css:
body {
	margin: 0;
	font-family: sans-serif;
}

/* The notes app's page-wide focus ring: it reaches html and body too, which a phone never focuses. */
:focus-visible {
	outline: 2px solid #1d4ed8;
	outline-offset: 2px;
}

a {
	color: #1d4ed8;
	text-decoration: none;
}

.note.mk-f1v2b2 {
				padding: 24px;
				background: #ffffff;
				color: #1d1b16;
				font-size: 18px;
			}
			.title.mk-f1v2b2 {
				margin: 0 0 12px;
				font-size: 24px;
			}
			.back.mk-f1v2b2 {
				display: block;
				padding: 8px 0;
			}
